import { test, expect } from '@playwright/test';

test.describe('Async Operation Cancellation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/async-operation');
  });

  test('should cancel an ongoing async operation using the Abort button', async ({ page }) => {
    // Verify the operation is in progress
    const operationStatus = page.getByRole('status', { name: /processing/i });
    await expect(operationStatus).toBeVisible();

    // Verify the operation is not completed
    const result = page.getByRole('status', { name: /completed/i });
    await expect(result).not.toBeVisible();

    // Verify the Abort button is visible
    const abortButton = page.getByRole('button', { name: /abort/i });
    await expect(abortButton).toBeVisible();

    // Click the Abort button to cancel the operation
    await abortButton.click();

    // Verify the operation status changes to cancelled
    await expect(operationStatus).toHaveTextContent(/cancelled/i);

    // Verify the operation result is not displayed
    await expect(result).not.toBeVisible();

    // Verify the operation is no longer in progress
    await expect(operationStatus).not.toBeVisible();

    // Verify the user is redirected to the success page
    const successPage = page.getByRole('heading', { name: /success/i });
    await expect(successPage).toBeVisible();

    // Verify the success message is displayed
    const successMessage = page.getByText(/operation cancelled/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle multiple abort attempts and prevent re-cancellation', async ({ page }) => {
    // Verify the operation is in progress
    const operationStatus = page.getByRole('status', { name: /processing/i });
    await expect(operationStatus).toBeVisible();

    // Verify the operation is not completed
    const result = page.getByRole('status', { name: /completed/i });
    await expect(result).not.toBeVisible();

    // Verify the Abort button is visible
    const abortButton = page.getByRole('button', { name: /abort/i });
    await expect(abortButton).toBeVisible();

    // Click the Abort button to cancel the operation
    await abortButton.click();

    // Verify the operation status changes to cancelled
    await expect(operationStatus).toHaveTextContent(/cancelled/i);

    // Verify the operation result is not displayed
    await expect(result).not.toBeVisible();

    // Verify the operation is no longer in progress
    await expect(operationStatus).not.toBeVisible();

    // Verify the user is redirected to the success page
    const successPage = page.getByRole('heading', { name: /success/i });
    await expect(successPage).toBeVisible();

    // Verify the success message is displayed
    const successMessage = page.getByText(/operation cancelled/i);
    await expect(successMessage).toBeVisible();

    // Click the Abort button again to attempt re-cancellation
    await abortButton.click();

    // Verify the operation status does not change
    await expect(operationStatus).toHaveTextContent(/cancelled/i);

    // Verify the operation result is still not displayed
    await expect(result).not.toBeVisible();

    // Verify the operation is still no longer in progress
    await expect(operationStatus).not.toBeVisible();

    // Verify the success message remains visible
    await expect(successMessage).toBeVisible();
  });
});
